                switch Homophone(char, "e", "i") {
                case .isAsciiEqual: return false
                case .isAsciiGreaterOrEqual: return char == "e" || char == "i"
                case .isAsciiLessOrEqual: return char == "e" || char == "i" || char == "a" || char == "o" || char == "u"
