```csharp
using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace RestServiceWrapper
{
    public abstract class RestServiceBase
    {
        private readonly string _baseUrl;
        private readonly string _authToken;
        private readonly HttpClient _httpClient;

        protected RestServiceBase(string baseUrl, string authToken)
        {
            _baseUrl = baseUrl;
            _authToken = authToken;
            _httpClient = new HttpClient();
            _httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {_authToken}");
        }

        protected async Task<TResponse> SendAsync<TResponse>(string requestUri, Func<HttpContent, CancellationToken, Task<TResponse>> responseConverter)
        {
            var requestMessage = new HttpRequestMessage(HttpMethod.Get, $"{_baseUrl}{requestUri}") { Timeout = TimeSpan.FromSeconds(30) };
            using (var response = await _httpClient.SendAsync(requestMessage, HttpCompletionOption.ResponseContent))
            {
                return await responseConverter(response.Content, CancellationToken.None);
            }
        }

        protected async Task<TResult> SendAsync<TRequest, TResult>(string requestUri, TRequest requestBody, Func<HttpContent, CancellationToken, Task<TResult>> responseConverter)
        {
            var requestMessage = new HttpRequestMessage(HttpMethod.Post, $"{_baseUrl}{requestUri}") { Content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(requestBody)), Timeout = TimeSpan.FromSeconds(30) };
            using (var response = await _httpClient.SendAsync(requestMessage, HttpCompletionOption.ResponseContent))
            {
                return await responseConverter(response.Content, CancellationToken.None);
            }
        }
    }

