function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];
        if ($ageA === $ageB) {
            // If ages are equal, sort by name
            return strnatcasecmp($a['name'], $b['name']);
        }
        return $order === 'ASC' ? $ageA < $ageB : $ageA > $ageB;
    });
    return $set;
}
```

